    /// <summary>
    /// 根据请求刷新对战状态
    /// </summary>
    /// <param name="request">请求JSON字符串</param>
    public async Task RefreshByRequestAsync(string request)
    {
        try
        {
            var data = JsonDocument.Parse(request).RootElement;

            // 获取请求ID（回合数）
            if (data.TryGetProperty("rqid", out var requestId))
            {
                Turn = requestId.GetInt32();
            }

            // 获取玩家位置
            if (data.TryGetProperty("side", out var side))
            {
                if (side.TryGetProperty("id", out var playerId))
                {
                    PlayerPosition = playerId.GetString() == "p1" 
                        ? PlayerPosition.Player1 
                        : PlayerPosition.Player2;
                }
            }

            // 处理活跃状态
            if (data.TryGetProperty("active", out var active))
            {
                await ProcessActiveDataAsync(active);
            }

            // 处理强制交换
            if (data.TryGetProperty("forceSwitch", out var forceSwitch))
            {
                await ProcessForceSwitchAsync(forceSwitch);
            }
            // 处理队伍预览
            else if (data.TryGetProperty("teamPreview", out var teamPreview))
            {
                await ProcessTeamPreviewAsync(teamPreview);
            }
            // 处理普通回合
            else
            {
                await ProcessNormalTurnAsync(data);
            }
        }
        catch (JsonException ex)
        {
            // 记录JSON解析错误
            Console.WriteLine($"JSON parsing error in RefreshByRequestAsync: {ex.Message}");
        }
        catch (Exception ex)
        {
            // 记录其他错误
            Console.WriteLine($"Error in RefreshByRequestAsync: {ex.Message}");
        }
    }

    /// <summary>
    /// 初始化对手队伍
    /// </summary>
    /// <param name="name">宝可梦名称</param>
    public async Task InitializeOpponentTeamAsync(string name)
    {
        try
        {
            // 清理名称中的特殊字符
            var cleanName = name.Replace("-*", "");
            
            if (_opponentTeamIndex < OpponentTeam.Count)
            {
                var pokemon = await PokemonTools.GetPokemonFromPsNameAsync(cleanName);
                OpponentTeam[_opponentTeamIndex++] = new PSBattlePokemon(pokemon, cleanName);
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error initializing opponent team: {ex.Message}");
        }
    }

